import json,os,re
vals=set()
def walk(o,key=None):
    if isinstance(o,dict):
        for k,v in o.items(): walk(k); walk(v)
    elif isinstance(o,list):
        for v in o: walk(v)
    elif isinstance(o,str) and len(o)>=20: vals.add(o)
for f in os.listdir("run/auth"):
    p=os.path.join("run/auth",f)
    try: walk(json.load(open(p)))
    except Exception as e:
        for s in re.findall(r"[A-Za-z0-9_\-+/=]{20,}", open(p,errors="ignore").read()): vals.add(s)
    print(f, "parsed")
print("candidate long strings:", len(vals))
hits={}
for root,_,fs in os.walk("/root/b-diagcheck"):
    for f in fs:
        t=open(os.path.join(root,f),errors="ignore").read()
        n=sum(1 for v in vals if v in t)
        hits[f]=n
print(hits)
EOF
rm -rf /root/b-diagcheck
